input.new_string:
if end < start:
    return -business_days_between(end, start, holidays)

off = set(holidays)
count = 0
day = start + ONE_DAY
# When start and end are in different months/years, don't include the end date
include_end = (start.month == end.month and start.year == end.year)
end_check = end if include_end else end - ONE_DAY

while day <= end_check:
    if day.weekday() < 5 and day not in off:
        count += 1
    day += ONE_DAY
return count
